var MSSTrusteesCallUtils = Class.create();
MSSTrusteesCallUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    insertInboundWidgetRecord: function(requestData, payload) { //MSSTRUSTES-50 - Insert Inbound Record.
        try {
            var eventsArray = [];
            var grWidget = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            grWidget.initialize();
            grWidget.object_id = requestData.objectid;
            grWidget.object_version = requestData.objectversion;
            grWidget.object_type = requestData.objecttype;
            grWidget.object_id_type = requestData.objectidtype;
            grWidget.event_status = requestData.eventstatus;
            grWidget.setValue('event_date_time', requestData.eventdatetime.replace('T', ' '));
            grWidget.source = requestData.source;
            grWidget.message_id = requestData.messageid;
            grWidget.event_type = requestData.eventtype;
            grWidget.additional_attributes = requestData.additionalattributes;
            grWidget.payload = JSON.stringify(payload);
            var widInbound = grWidget.insert();
            if (widInbound != '') {
                this.createautomatedAMLKYCCase(widInbound);
                eventsArray.push({
                    'Status': '200',
                });
            }
            return eventsArray;
        } catch (e) {
            gs.info('Script Include -MSSTrusteesCallUtils: insertInboundWidgetRecord - Unknown exception while processing Widget Inbound Request ' + e.message);
        }
    },

    insertInboundWidgetRecordComp: function(requestData, payload) { // MSSTRUSTES-50 - Insert Inbound Record.
        try {
            var eventsArray = [];
            var grEmail = new GlideRecord('x_hsb11_hsbc_mss_o_mss_email_inbound');
            grEmail.initialize();
            grEmail.object_id = requestData.objectid;
            grEmail.object_version = requestData.objectversion;
            grEmail.object_type = requestData.objecttype;
            grEmail.object_id_type = requestData.objectidtype;
            grEmail.event_status = requestData.eventstatus;
            grEmail.setValue('event_date_time', requestData.eventdatetime.replace('T', ' '));
            grEmail.source = requestData.source;
            grEmail.message_id = requestData.messageid;
            grEmail.event_type = requestData.eventtype;
            grEmail.additional_attributes = requestData.additionalattributes;
            grEmail.payload = JSON.stringify(payload);
            var emaInbound = grEmail.insert();
            if (emaInbound != '') {
                this.checkAndProcessDuplicateCase(emaInbound);
                eventsArray.push({
                    'Status': '200',
                });
            }
            return eventsArray;
        } catch (e) {
            gs.info('Script Include -MSSTrusteesCallUtils: insertInboundWidgetRecordComp - Unknown exception while processing Widget Inbound Request ' + e.message);
        }
    },

    createOutboundRecord: function(caseId, payload, methodname, scheme_code, subcategory) { //MSSTRUSTES-43
        try {
            var outboundGR = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            outboundGR.initialize();
            outboundGR.request_body = JSON.stringify(payload);
            outboundGR.request_type = 'Post Payload';
            outboundGR.source_table = 'x_hsb11_mss_trus_0_aml_kyc_case';
            outboundGR.sys_scope = "b208a7c083689e50c6695855eeaad3d2";
            outboundGR.document_id = caseId;
            outboundGR.request_date = new GlideDateTime();
            var outboundId = outboundGR.insert();

            if (outboundId) {
                this.triggerOutboundRestMessage(payload, outboundId, methodname, scheme_code, subcategory);
            }
        } catch (error) {
            gs.info('Error in function createOutboundRecord : ' + error.message);
        }
    },

    updateOutboundrecord: function(caseId, payload, methodname, scheme_code, subcategory) { //MSSTRUSTES-43
        try {
            var outboundGR = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            outboundGR.addQuery('document_id', caseId);
            outboundGR.query();
            if (outboundGR.next()) {
                outboundGR.request_body = JSON.stringify(payload);
                outboundGR.request_date = new GlideDateTime();
                var outboundId = outboundGR.update();
            }
            if (outboundId) {
                this.triggerOutboundRestMessage(payload, outboundId, methodname, scheme_code, subcategory);
            }
        } catch (error) {
            gs.info('Error in function updateOutboundrecord : ' + error.message);
        }

    },

    triggerOutboundRestMessage: function(payload, outboundId, queryParam, scheme_code, subcategory) { //MSSTRUSTES-43
        try {

            var trustess_channel_endpoint = gs.getProperty('x_hsb11_mss_trus_0.aml_kyc_outbound_endpoint');
            var trustes_token = gs.getProperty('x_hsb11_mss_trus_0.aml_kyc_outbound_token');

            var endpoint = trustess_channel_endpoint + scheme_code + '/' + queryParam;

            var restMessage = new sn_ws.RESTMessageV2('MSS Trustees AMLKYC API', 'postDataChannelService');
            restMessage.setEndpoint(endpoint);
            restMessage.setStringParameterNoEscape('trustes_token', trustes_token);
            restMessage.setRequestBody(JSON.stringify(payload));

            var response = restMessage.executeAsync();
            var responseBody = response.getBody();

            var parsedResponse = JSON.parse(responseBody);
            var httpStatus = parsedResponse.status;
            var groutbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            if (groutbound.get(outboundId)) {
                groutbound.response_date = new GlideDateTime();
                if (httpStatus == '200' || httpStatus == '201') {
                    groutbound.response_body = responseBody.toString();
                    //groutbound.error_code = httpStatus;
                    responseBody = responseBody.toString();
                    groutbound.state = 'Processed';
                    groutbound.update();
                    if (queryParam == 'save-risk-info') {
                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Loopback to Channel Services Success.');
                    } else {
                        this.updatemanualAMLKYCcase(parsedResponse, groutbound.document_id, subcategory);
                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Fetched Data from Channel Services Successfully.');
                    }


                } else if ((httpStatus == '500' || httpStatus == '503') && queryParam == 'save-risk-info') { //Retry logic - for loopback
                    var count = groutbound.getValue('retry_count');
                    var time = gs.getProperty('x_hsb11_mss_trus_0.aml_kyc_loopback_retry_time');
                    if (count < 2) {
                        count++;
                        groutbound.state = 'Error';
                        groutbound.response_body = responseBody.toString();
                        groutbound.error_code = httpStatus;
                        groutbound.error_body = responseBody.toString();
                        groutbound.retry_count = count;
                        groutbound.update();
                        var processTime = new GlideDateTime();
                        processTime.addSeconds(time);
                        gs.eventQueueScheduled('x_hsb11_mss_trus_0.retry_loopback_data', groutbound, groutbound.sys_id, groutbound.document_id, processTime);

                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Loopback to Channel Services Failed. Retrying..');

                    } else {
                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Loopback to Channel Services Failed. Retrying..');
                    }

                } else {
                    if (queryParam == 'save-risk-info') {
                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Loopback to Channel Services Failed. To check if the data entered is available with SSv');
                    } else {
                        var errorMsg = parsedResponse.errorInfo && parsedResponse.errorInfo.length > 0 ? parsedResponse.errorInfo[0].msg : 'Unknown error';
                        groutbound.state = 'Error';
                        groutbound.response_body = responseBody.toString();
                        groutbound.error_code = httpStatus;
                        groutbound.error_body = responseBody.toString();
                        groutbound.retry_count = count;
                        groutbound.update();
                        gs.addErrorMessage('Fetching Details from Channel Services Failed.   ' + 'Reason: ' + errorMsg);
                        this.updateTaskandCaseLoopBack(groutbound.document_id, responseBody, httpStatus, 'Data Fetch Error. To check if the data entered is available with SSv');
                    }
                }
            }
        } catch (error) {
            gs.addErrorMessage('Fetching Details from Channel Services Failed.   ' + 'Reason: ' + error.message);
            gs.error('Error while triggering REST message: ' + error.message);
        }

    },

    updateTaskandCaseLoopBack: function(caseId, responsebody, status, work_notes) { //MSSTrustes-60
        var grCase = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case');
        if (grCase.get(caseId)) {
            grCase.work_notes = work_notes;
            grCase.update();
        }
        var grCaseTask = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case_task');
        grCaseTask.addQuery('aml_kyc_case', caseId);
        grCaseTask.query();
        while (grCaseTask.next()) { //Update All Case Tasks
            grCaseTask.work_notes = work_notes;
            grCaseTask.update();
        }


    },
    updatemanualAMLKYCcase: function(response, caseId, subcategory) { //MSSTRUSTES-43
        try {
            var data = response.data[0];
            var grCase = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case');
            if (grCase.get(caseId)) {
                switch (subcategory) {
                    case 'er':
                        this.mapAMLKYCERFields(grCase, data);
                        break;
                    case 'ee':
                        this.mapAMLKYCEEFields(grCase, data);
                        break;
                    default:
                        break;
                }
                if (data.beneficialOwnerList)
                    this.insertAMLCaseDetailsBeneficialOwner(caseId, data.beneficialOwnerList, 3);
                if (data.principalParticularList)
                    this.insertAMLCaseDetailsDirectorPrincipal(caseId, data.principalParticularList, 2);
                if (data.authorizedPersonList)
                    this.insertAMLCaseDetailsConnectedPerson(caseId, data.authorizedPersonList, 1);
                grCase.update();
                gs.addInfoMessage('Fetched Data From Channel Services for case ID: ' + grCase.number);
            }
        } catch (error) {
            gs.addErrorMessage('Fetching Data From Channel Services Failed for ' + grCase.number + '. Error: ' + error.message);
            gs.info('Error Case Updation failed - updatemanualAMLKYCcase: ' + error.message);
        }
    },

    createautomatedAMLKYCCase: function(inboundSysID) { //MSSTRUSTES-50 Create AML/KYC Case 
        //MSSTrustes-67 & MSSTrustes-78 & MSSTRUSTES-146
        try {
            var grInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_widget_inbound');
            if (grInbound.get(inboundSysID)) {
                var payload = grInbound.payload;
                var grCase = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case');
                grCase.initialize();
                grCase.state = '1';
                payload.replace(/\\/g, '\\\\');
                var parseToJson = JSON.parse(payload);
                var payloadData = JSON.parse(parseToJson.data);
                var eventStatus = grInbound.event_status;
                switch (eventStatus.toString()) {
                    case 'EE_ENROLLMENT':
                        this.mapAMLKYCEEFields(grCase, payloadData);
                        grCase.category_aml = 'new_enrollment';
                        grCase.sub_category = 'ee';
                        break;
                    case 'ER_ENROLLMENT':
                        this.mapAMLKYCERFields(grCase, payloadData);
                        grCase.category_aml = 'new_enrollment';
                        grCase.sub_category = 'er';
                        break;
                    case 'PERIOD_ER_REVIEW':
                        this.mapAMLKYCERFields(grCase, payloadData);
                        grCase.category_aml = 'periodic_review_query';
                        grCase.sub_category = 'er';
                        break;
                    case 'PERIOD_EE_REVIEW':
                        this.mapAMLKYCEEFields(grCase, payloadData);
                        grCase.category_aml = 'periodic_review_query';
                        grCase.sub_category = 'ee';
                        break;
                    case 'TRANSACTION_MONITOR_RULE1':
                    case 'TRANSACTION_MONITOR_RULE2':
                    case 'TRANSACTION_MONITOR_RULE3':
                    case 'TRANSACTION_MONITOR_RULE4':
                    case 'TRANSACTION_MONITOR_RULE5':
                    case 'TRANSACTION_MONITOR_RULE11':
                        var match = eventStatus && eventStatus.match(/TRANSACTION_MONITOR_RULE(\d+)/);
                        if (match) {
                            var ruleNum = match[1]; // This will be '1', '2', ..., '5', '11', etc.
                            grCase.category_aml = 'rule_' + ruleNum;
                        }
                        this.mapAMLKYCTMFields(grCase, payloadData);
                        break;

                    default:
                        break;
                }
                var amlCaseSysId = grCase.insert();
                this.insertAMLCaseDetailsBeneficialOwner(amlCaseSysId, payloadData.beneficialOwnerList, 3);
                this.insertAMLCaseDetailsDirectorPrincipal(amlCaseSysId, payloadData.principalParticularList, 2);
                this.insertAMLCaseDetailsConnectedPerson(amlCaseSysId, payloadData.authorizedPersonList, 1);
            }
        } catch (e) {
            gs.info('Script Include - x_hsb11_mss_trus_0.MSSTrusteesCallUtils: createAMLKYCCase - Error ' + e.message);
        }
    },

    mapAMLKYCEEFields: function(grCase, data) { //MSSTRUSTES-69 - EE Fields MSSTrustes-78
        try {
            grCase.scheme_code = data.schemeCode;
            if ((data.hKIdNumber != null && data.hKIdCheckDigit != null) && (data.hKIdNumber != "" && data.hKIdCheckDigit != "") && (data.hKIdNumber != '' && data.hKIdCheckDigit != ''))
                grCase.identification_hkid_card_auth_pers_1 = data.hKIdNumber + '(' + data.hKIdCheckDigit + ')';
            grCase.identification_passportno_auth_pers_1 = data.passport;
            grCase.given_name_in_english_auth_pers_1 = data.firstName;
            grCase.surname_in_english_auth_pers_1 = data.lastName;
            grCase.given_name_in_chinese_auth_pers_1 = data.firstZhName;
            grCase.surname_in_chinese_auth_pers_1 = data.lastZhName;
            grCase.language_er = data.languageType;
            grCase.email_address_auth_pers_1 = data.email;
            grCase.title_ee = data.title;
            // grCase.title_auth_pers_1 = data.title;
            // grCase.language_type_auth_pers_1 = data.languageType;
            // grCase.email_auth_pers_1 = data.email;
            grCase.date_of_birth_auth_pers_1 = data.dateOfBirth;
            grCase.place_of_birth_ee = data.placeOfBirth;
            grCase.nationality_1_auth_pers_1 = data.nationality1;
            grCase.nationality_2_auth_pers_1 = data.nationality2;
            grCase.nationality_3_auth_pers_1 = data.nationality3;
            grCase.gender_ee = data.gender;
            grCase.occupation = data.occupation;
            grCase.job_title_occupation = data.jobPosition;
            grCase.nature_of_business = data.businessNature;
            grCase.member_account_1_status_ee = data.statusCode;
            grCase.source_of_fund = data.sourceOfFund;
            grCase.regular_contribution = data.contributionAmount;
            grCase.organisation_type = data.companyType;
            grCase.company_name_english = data.companyName;
            grCase.company_name_chinese = data.companyChineseName;
            grCase.registration_type = data.registrationType;
            grCase.registration_number = data.registrationNumber; //MStrustes-287
            grCase.business_other_registration_no = data.registrationNumber;
            grCase.branch_number = data.branchNumber;
            var isSEP = false;
            //Member Account (For upto 5 members)
            if (data.memberAccountList && data.memberAccountList.length > 0) {
                var index = 1;
                data.memberAccountList.forEach(memberAccount => {
                    switch (index) {
                        case 1:
                            grCase.member_account_1_status_ee = memberAccount.statusCode;
                            grCase.member_account_code_1_ee = memberAccount.memberAccountCode;
                            grCase.member_account_type_1_ee = memberAccount.type;
                            if (memberAccount.type == 'SEP')
                                isSEP = true;
                            index++;
                            break;
                        case 2:
                            grCase.member_account_2_status_ee = memberAccount.statusCode;
                            grCase.member_account_code_2_ee = memberAccount.memberAccountCode;
                            grCase.member_account_type_2_ee = memberAccount.type;
                            index++;
                            break;

                        case 3:
                            grCase.member_account_3_status_ee = memberAccount.statusCode;
                            grCase.member_account_code_3_ee = memberAccount.memberAccountCode;
                            grCase.member_account_type_3_ee = memberAccount.type;
                            index++;
                            break;

                        case 4:
                            grCase.member_account_4_status_ee = memberAccount.statusCode;
                            grCase.member_account_code_4_ee = memberAccount.memberAccountCode;
                            grCase.member_account_type_4_ee = memberAccount.type;
                            index++;
                            break;

                        case 5:
                            grCase.member_account_5_status_ee = memberAccount.statusCode;
                            grCase.member_account_code_5_ee = memberAccount.memberAccountCode;
                            grCase.member_account_type_5_ee = memberAccount.type;
                            index++;
                            break;
                    }
                });
            }
            //Address 
            if (data.addressList && data.addressList.length > 0) {
                data.addressList.forEach(address => {
                    switch (address.typeCode) {
                        case "CORRESP":
                            grCase.er_employer_correspondence_address_type = address.typeCode;
                            grCase.er_employer_correspondence_address_format = address.formatType;
                            grCase.er_employer_correspondence_address_room = address.room;
                            grCase.er_employer_correspondence_address_floor = address.floor;
                            grCase.er_employer_correspondence_address_block = address.block;
                            grCase.er_employer_correspondence_address_building = address.building;
                            grCase.er_employer_correspondence_address_street = address.street;
                            grCase.er_employer_correspondence_address_district = address.district;
                            grCase.er_employer_correspondence_address_city_or_area = address.city;
                            grCase.er_employer_correspondence_address_country = address.country;
                            grCase.er_employer_correspondence_address_postal_code = address.postalCode;
                            grCase.er_employer_correspondence_address_chinese_address_flag = address.chineseAddressFlag;
                            grCase.er_employer_correspondence_address_status = address.statusCode;
                            break;

                        case "RESIDENTIAL":
                            grCase.residential_address_block_auth_pers_1 = address.block;
                            grCase.residential_address_building_auth_pers_1 = address.building;
                            grCase.residential_address_chinese_address_flag_auth_pers_1 = address.chineseAddressFlag;
                            grCase.residential_address_country_auth_person_1 = address.country;
                            grCase.residential_address_city_or_area_auth_pers_1 = address.city;
                            grCase.residential_address_district_auth_pers_1 = address.district;
                            grCase.residential_address_floor_auth_pers_1 = address.floor;
                            grCase.residential_address_format_auth_pers_1 = address.formatType;
                            grCase.residential_address_postal_code_auth_pers_1 = address.postalCode;
                            grCase.residential_address_room_auth_pers_1 = address.room;
                            grCase.residential_address_status_auth_pers_1 = address.statusCode;
                            grCase.residential_address_street_auth_pers_1 = address.street;
                            grCase.residential_address_type_auth_pers_1 = address.typeCode;
                            break;

                        case "BUSINESS":
                            if (isSEP) {


                                grCase.business_address_type_sepa = address.typeCode;
                                grCase.business_address_format = address.formatType;
                                grCase.business_address_room = address.room;
                                grCase.business_address_floor = address.floor;
                                grCase.business_address_block = address.block;
                                grCase.business_address_building = address.building;
                                grCase.business_address_street = address.street;
                                grCase.business_address_district = address.district;
                                grCase.business_address_city_or_area = address.city;
                                grCase.business_address_country = address.country;
                                grCase.business_address_postal_code = address.postalCode;
                                grCase.business_address_chinese_address_flag = address.chineseAddressFlag;
                                grCase.business_address_status = address.statusCode;

                            }
                            break;

                    }
                });
            }




            //For Tax-  only the 5 Jurisdiction of Tax field available
            if (data.taxResidenceList && data.taxResidenceList.length > 0) {
                var idx = 1;
                data.taxResidenceList.forEach(taxResidence => {
                    switch (idx) {
                        case 1:
                            grCase.reason_without_tin_1 = taxResidence.reasonWithoutTaxNumber;
                            grCase.tin_1 = taxResidence.taxNumber;
                            grCase.jurisdiction_of_tax_residency_1 = taxResidence.residenceJurisdiction;
                            idx++;
                            break;
                        case 2:
                            grCase.reason_without_tin_2 = taxResidence.reasonWithoutTaxNumber;
                            grCase.tin_2 = taxResidence.taxNumber;
                            grCase.jurisdiction_of_tax_residency_2 = taxResidence.residenceJurisdiction;
                            idx++;
                            break;
                        case 3:
                            grCase.reason_without_tin_3 = taxResidence.reasonWithoutTaxNumber;
                            grCase.tin_3 = taxResidence.taxNumber;
                            grCase.jurisdiction_of_tax_residency_3 = taxResidence.residenceJurisdiction;
                            idx++;
                            break;

                        case 4:
                            grCase.reason_without_tin_4 = taxResidence.reasonWithoutTaxNumber;
                            grCase.tin_4 = taxResidence.taxNumber;
                            grCase.jurisdiction_of_tax_residency_4 = taxResidence.residenceJurisdiction;
                            idx++;
                            break;

                        case 5:
                            grCase.reason_without_tin_5 = taxResidence.reasonWithoutTaxNumber;
                            grCase.tin_5 = taxResidence.taxNumber;
                            grCase.jurisdiction_of_tax_residency_5 = taxResidence.residenceJurisdiction;
                            idx++;
                            break;

                    }
                });
            }


            //Using ER fields
            if (data.aMLRiskSummaryList && data.aMLRiskSummaryList.length > 0) {
                var aMLRiskSummary = data.aMLRiskSummaryList[0];
                if (aMLRiskSummary) {
                    //MSSTRustes-230 250
                    //MSSTRUSTES-443
                    grCase.bank_last_review_date_er_risk = aMLRiskSummary.lastReviewDate;
                    grCase.bank_common_fcrr_er_risk = aMLRiskSummary.financialCrimeRiskRating;
                    grCase.bank_common_customer_er_risk = aMLRiskSummary.bankCommonCustomer;
                    grCase.override_by_bank_er_risk = aMLRiskSummary.overrideByBank;
                    grCase.last_fcrr_result_er_risk = aMLRiskSummary.fCRRResult;
                    grCase.last_fcrr_effective_date_er_risk = aMLRiskSummary.fCRREffectiveDate;


                    grCase.last_flag_aml_type_1_er_risk = aMLRiskSummary.internalTrack;
                    grCase.last_flag_aml_type_1_effective_date_er_risk = aMLRiskSummary.effectiveDate;
                    grCase.empf_aml_type_1_2_3_proposed_er_risk = aMLRiskSummary.proposeAMLType;
                    grCase.superhold_transaction_blocking_er_risk = aMLRiskSummary.transactionBlock;
                    grCase.super_trans_blocking_effective_date_er_risk = aMLRiskSummary.transBlockEffectiveDate;
                    grCase.note_history_er_risk = aMLRiskSummary.note; //MSStrustes-279&285
                    grCase.note_history_effective_date_er_risk = aMLRiskSummary.noteEffectiveDate; //MSStrustes-279&285
                    // grCase.fcrr_result_er_risk = aMLRiskSummary.fCRRResult;
                    // grCase.fcrr_effective_date_er_risk = aMLRiskSummary.fCRREffectiveDate;
                    grCase.overall_aml_risk_level_er_risk = aMLRiskSummary.riskLevel;
                    grCase.empf_aml_type_1_er_risk = aMLRiskSummary.aMLType1;
                    grCase.empf_aml_type_2_er_risk = aMLRiskSummary.aMLType2;
                    grCase.empf_aml_type_3_er_risk = aMLRiskSummary.aMLType3;
                    grCase.effective_date_of_aml_type_1_er_risk = aMLRiskSummary.aMLType1EffectiveDate;
                    grCase.effective_date_of_aml_type_2_er_risk = aMLRiskSummary.aMLType2EffectiveDate;
                    grCase.effective_date_of_aml_type_3_er_risk = aMLRiskSummary.aMLType3EffectiveDate;
                    grCase.end_date_of_aml_type_1_er_risk = aMLRiskSummary.aMLType1EndDate;
                    grCase.end_date_of_aml_type_2_er_risk = aMLRiskSummary.aMLType2EndDate;
                    grCase.end_date_of_aml_type_3_er_risk = aMLRiskSummary.aMLType3EndDate;

                }
            }

            //Adding ee id
            grCase.ee_id = data.eMPFId;




        } catch (error) {
            gs.info('Error in field mapping - mapAMLKYCEEFields: ' + error.message);
        }


    },

    mapAMLKYCERFields: function(grCase, data) { //MSSTRUSTES-68 - Map ER Fields
        try {

            grCase.scheme_code = data.schemeCode;
            grCase.employer_account_type = data.employerAccountType;
            grCase.employer_account_code = data.employerAccountCode;
            grCase.employer_account_status = data.statusCode;
            grCase.company_name_english = data.companyName;
            grCase.company_name_chinese = data.companyChineseName;
            grCase.registration_type = data.registrationType;
            //grCase.registration_number = data.registrationNumber; //MSSTrustes-193
            grCase.business_other_registration_no = data.registrationNumber;
