    checkAndProcessDuplicateCase: function(inboundSysID) { //MSSTRUSTES-243
        try {
            // Get inbound record
            var grInbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_email_inbound');
            if (grInbound.get(inboundSysID)) {
                var payload = JSON.parse(grInbound.payload.toString());
				var messageID = grInbound.message_id;

                // Check for duplicate case
                var grCase = new GlideRecord('x_hsb11_mss_trus_0_complaint_case');
                grCase.addQuery('query_id', payload.Email_QueryId);
                grCase.query();
                if (!grCase.next()) {
                    this.createautoCompEscaCase(payload, messageID);
                } else {
                    var status = "SERVICENOW_EMAIL_REJECTED";
                    var id = grCase.sys_id;
                    this.triggersendEmailApi(status, id, messageID);
                }
            }
        } catch (e) {
            gs.error('Script Include:MSSTrusteesCallUtils: checkAndProcessDuplicateCase - Unknown exception while triggering rest api ' + e.message);
        }
    },

    triggersendEmailApi: function(status, id, messageID) {
        try {
			var intStatus = false;
            var outboundGR = new GlideRecord('x_hsb11_hsbcmss_qw_hsbc_qtrack_message_outbound');
            outboundGR.initialize();
            outboundGR.qtrack_id = messageID;
            outboundGR.email_status = status;
            outboundGR.source_table = 'x_hsb11_mss_trus_0_complaint_case';
            outboundGR.document_id = id;
            outboundGR.sys_scope = "b208a7c083689e50c6695855eeaad3d2";
            outboundGR.request_date = new GlideDateTime();
            var outboundId = outboundGR.insert();

            // Re-query outbound record for update
            if (outboundGR.get(outboundId)) {
                var qtrackenv = gs.getProperty('x_hsb11_hsbcmss_qw.qtrack_url');
                var qtrackToken = gs.getProperty('x_hsb11_hsbcmss_qw.qtrack_api_token');

                var r = new sn_ws.RESTMessageV2('x_hsb11_hsbcmss_qw.HSBC QTrack outbound email status', 'Default Put');
                r.setStringParameterNoEscape('qtrack_base_uri', qtrackenv);
                r.setStringParameterNoEscape('qtrack_token', qtrackToken);
                r.setStringParameterNoEscape('serviceNowId', outboundGR.document_id.toString());
                r.setStringParameterNoEscape('status', outboundGR.email_status.toString());
                r.setStringParameterNoEscape('queryMailId', outboundGR.qtrack_id.toString());

                var response = r.executeAsync();
                var responseBody = response.getBody();
                var httpStatus = response.getStatusCode();

                outboundGR.response_date = new GlideDateTime();
                if (httpStatus == '200') {
                    outboundGR.response_body = responseBody;
                    outboundGR.state = "Processed";
					intStatus= true;

                } else {
                    outboundGR.error_code = httpStatus;
                    outboundGR.error_body = responseBody;
                    outboundGR.state = 'Error';

                }
                outboundGR.update();
            }
			return intStatus;
        } catch (e) {
            gs.error('Script Include:MSSTrusteesCallUtils: triggersendEmailApi - Unknown exception while triggering rest api ' + e.message);
        }

    },

    createautoCompEscaCase: function(payloadData, messageid) { //MSSTRUSTES-242
        try {
            // Initialize new complaint case GlideRecord
            var grCase = new GlideRecord('x_hsb11_mss_trus_0_complaint_case');
            grCase.initialize();

            // Set static fields from payloadData
            grCase.email_queryid = payloadData.Email_QueryId;
            grCase.u_sender = payloadData.Email_Headers.Sender;
            grCase.u_receiver = payloadData.Email_Headers.recipients;
            grCase.subject =payloadData.Email_Subject;
            grCase.query_id = payloadData.Email_QueryId;
            grCase.url = payloadData.HyperLink;
			grCase.u_message_id = messageid;
            grCase.x_email_body = `<p>Dear BCT,</p>
    <p>
      Please find below the summary of the case <strong>${payloadData.Email_Subject+ " - " + payloadData.Email_QueryId}</strong> and the follow up action where applicable.
    </p>
    <p><b>Escalation Reason:</b> <font color="red">[To be Added]</font></p>
    <p><b>Resolution:</b> <font color="red">[To be Added]</font></p>
    <p><b>Follow Up Action:</b> <font color="red">[To be Added]</font></p>
    <p><b>Attachment:</b> <font color="red">[To be Added]</font></p>
    <p>
        Please be informed that the case is now closed. A new case will be raised for further follow up if required.
    </p>`;
            grCase.state = '1';
            // Define keywords and their corresponding field names
            var keywordFieldMap = {
                "Reference No": "u_reference_number",
                "Employer Account No.": "u_employer_id", //MSSTRUSTES-366
                "Member HKID No. or Passport No.": "u_member_id",
                "Type of request": "u_type_of_request",
                "Scheme Member Account No.": "scheme_number",
                "Type of process": "u_type_of_process",
                "Original received date of client’s request": "original_received_date",
                "Date of case sent to HSBC": "date_of_case_sent",
                "Escalation reason": "u_escalation_reason",
                "Reply due date": "reply_due_date",
                "Urgent case indicator": "urgent_case_indicator",
                "Name of document Attached": "name_of_document"
            };

            //Define normalization maps for choice fields
            // var typeOfProcessMap = {
            //     "aml": "AML",
            //     "kyc": "KYC",
            //     "client record maintenance": "Client record maintenance",
            //     "contribution": "Contribution",
            //     "termination & claims": "Termination & Claims"
            // };

            var typeOfRequestMap = {
                "complaint": "Complaint",
                "escalation": "Escalation",
                "inquiry": "Inquiry"
            };

            //Parse HTML email body and extract field values
            var html = payloadData.Email_Body;
            var result = {};
            var rowRegex = /<tr[\s\S]*?<\/tr>/gi;
            var cellRegex = /<td[\s\S]*?>([\s\S]*?)<\/td>/gi;
            var rows = html.match(rowRegex);
            if (rows) {
                for (var i = 0; i < rows.length; i++) {
                    var cells = [];
                    var cellMatch;
                    while ((cellMatch = cellRegex.exec(rows[i])) !== null) {
                        // Remove HTML tags and extra spaces from cell text
                        var text = cellMatch[1].replace(/<[^>]+>/g, '').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').replace(/amp;/g, '').trim();
                        cells.push(text);
                    }
                    // Map extracted label to ServiceNow field if keyword matches
                    if (cells.length >= 2) {
                        var label = cells[0].toLowerCase();
                        var cellValue = cells[1].trim(); // Renamed from 'value' to 'cellValue'
                        for (var keyword in keywordFieldMap) {
                            if (label.indexOf(keyword.toLowerCase()) !== -1) {
                                var snField = keywordFieldMap[keyword];
                                result[snField] = cellValue;
                                break;
                            }
                        }
                    }
                }
            }

            //Set extracted values to GlideRecord fields, normalize choice fields and convert date formats
            for (var key in result) {
                var value = result[key];
                // Convert date format for date fields
                if (
                    key === 'reply_due_date' ||
                    key === 'original_received_date' ||
                    key === 'date_of_case_sent'
                ) {
                    grCase[key] = convertDateFormat(value);
                }
                // Normalize choice fields for ServiceNow
                // else if (key === 'u_type_of_process') {
                //     //grCase[key] = normalizeChoice(value, typeOfProcessMap);
                // 	var decodedValue = GlideStringUtil.unescapeHTML(value);
                // 	grCase[key] = decodedValue;
                // } 
                else if (key === 'u_type_of_request') {
                    grCase[key] = normalizeChoice(value, typeOfRequestMap);
                }
                // Set other fields directly
                else {
                    grCase[key] = value;
                }
            }

            //Insert the new complaint case record
            grCase.insert();

        } catch (e) {
            //Log error if any exception occurs
            gs.error('Script Include - x_hsb11_mss_trus_0.MSSTrusteesCallUtils: createautoCompEscaCase - Unknown exception while creating case from widget inbound record ' + e.message);
        }

        // Helper function: Normalize user input for choice fields
        function normalizeChoice(value, map) {
            var normalized = value.toLowerCase().replace(/[^a-z& ]/g, '').replace(/\s+/g, ' ').trim();
            for (var key in map) {
                if (normalized.indexOf(key) !== -1) {
                    return map[key];
                }
            }
            return value;
        }

        // Helper function: Convert date format from dd/mm/yyyy to yyyy-mm-dd
        function convertDateFormat(dateStr) {
            var parts = dateStr.split('/');
            if (parts.length === 3) {
                return parts[2] + '-' + parts[1].padStart(2, '0') + '-' + parts[0].padStart(2, '0');
            }
            return dateStr;
        }
    },
