    //MSSTrustes-184
    getUserTrusteeGroups: function() {
        var userSysId = this.getParameter('sysparm_userSysId');
        var groupSysIds = [];

        // First, get all group sys_ids the user is a member of
        var grMember = new GlideRecord('sys_user_grmember');
        grMember.addQuery('user', userSysId);
        grMember.query();
        while (grMember.next()) {
            groupSysIds.push(grMember.group.toString());
        }

        // Now, query the routing table for case task
        var grRoute = new GlideRecord('x_hsb11_mss_trus_0_mss_trustees_routing_table_for_case_task');
        grRoute.addQuery('active', true);
        grRoute.addQuery('u_caseassignmentgroup', 'IN', groupSysIds.join(','));
        grRoute.query();
        var groupChoices = [];
        while (grRoute.next()) {
            var schemaCode = grRoute.schema_code + '';
            var displayValue = grRoute.schema_code.getDisplayValue();
            if (schemaCode && !groupChoices.some(function(choice) {
                    return choice.value === schemaCode;
                })) {
                groupChoices.push({
                    value: schemaCode,
                    label: displayValue
                });
            }
        }

        return JSON.stringify(groupChoices); // Return as JSON string for GlideAjax
    },

    //MSSTrustes-132.
    isUserInAssignmentGroup: function() {
        var groupSysId = this.getParameter('sysparm_groupSysId'); // Get group sys_id from client
        var userSysId = gs.getUserID();
        var gr = new GlideRecord('sys_user_grmember');
        gr.addQuery('group', groupSysId);
        gr.addQuery('user', userSysId);
        gr.query();
        return gr.hasNext() ? 'true' : 'false'; // Return true/false as a string
    },

