    //TODO CReate another function which will be triggered for creating automatic case of EE


    updateLoopBackAndNotify: function(caseId, responsebody, status) {
        //To integrate xMatter for notification.
        var grCase = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case');
        var grCaseTask = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case_task');
        grCaseTask.addQuery('aml_kyc_case', caseId);
        if (grCase.get(caseId))
            grCase.work_notes = 'LoopBack to Channel Services Failed. Retry Limit Exceeded.';
        grCaseTask.query();
        while (grCaseTask.next()) {
            grCaseTask.work_notes = 'LoopBack to Channel Services Failed. Retry Limit Exceeded';
            grCaseTask.update();
        }
        grCase.update();
    },


    gettaskassigned: function() {

        var caseId = this.getparameter('syspram_case_id');
        var taskGR = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case_task');
        taskGR.addQuery('aml_kyc_case', caseId);
        taskGR.orderByDesc('sys_created_on');
        taskGR.setLimit(1);
        taskGR.query();
        if (taskGR.next()) {
            return taskGR.assigned_to.toString();

        }



    },

    insertCompInboundRecord: function() {
        try {
            var caseID = this.getParameter('sysparm_sysid');
            var sender = this.getParameter('sysparm_sender');
            var receivers = this.getParameter('sysparm_receivers');
            var subject = this.getParameter('sysparm_subject');
            var body = this.getParameter('sysparm_body');
            var sendReply = this.getParameter('sysparm_sendReply');
            var files = this.getParameter('sysparm_files');
            var payload = {
                "sender": sender,
                "receivers": receivers,
                "Subject": subject,
                "body": body,
                "sendReply": sendReply,
                "files": files
            };
            var parsepayload = JSON.stringify(payload);

            var outboundGR = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
            outboundGR.initialize();
            outboundGR.request_body = parsepayload;
            outboundGR.source_table = 'x_hsb11_mss_trus_0_complaint_case';
            outboundGR.sys_scope = "b208a7c083689e50c6695855eeaad3d2";
            outboundGR.document_id = caseID;
            outboundGR.request_date = new GlideDateTime();
            var outboundId = outboundGR.insert();
            // if (outboundId) {
            //     this.triggerCompRestMessage(outboundGR.request_body, outboundId);
            // }
            return "success";
        } catch (err) {
            return err.message + "failure";
        }
    },
    //MSSTRUSTES-142,141
    triggerCompRestMessage: function(payload, outboundId) {
        var qtrack_endpoint = gs.getProperty('x_hsb11_hsbc_mss_o.complaint _qtrack_endpoint');
        var qtrack_token = gs.getProperty('x_hsb11_hsbc_mss_o.complaint _qtrack_token');

        var endpoint = trustess_channel_endpoint;

        var restMessage = new sn_ws.RESTMessageV2('HSBC MSS QTrack API', 'postOutbondEmail');
        restMessage.setEndpoint(endpoint);
        restMessage.setStringParameterNoEscape('qtrack_token', qtrack_token);
        restMessage.setRequestBody(JSON.stringify(payload));

        var response = restMessage.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        var parsedResponse = JSON.parse(responseBody);

        var groutbound = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_outbound');
        if (groutbound.get(outboundId)) {
            groutbound.response_date = new GlideDateTime();
            if (httpStatus == '200' || httpStatus == '201') {
                groutbound.response_body = responseBody.toString();
                groutbound.error_code = httpStatus;
                responseBody = responseBody.toString();
                groutbound.state = 'Processed';
                groutbound.update();

            } else if (httpStatus == '500') { //Retry logic - for loopback
                var count = groutbound.getValue('retry_count');
                var time = gs.getProperty('x_hsb11_mss_trus_0.aml_kyc_loopback_retry_time');
                if (count < 2) {
                    count++;
                    groutbound.state = 'Error';
                    groutbound.response_body = responseBody.toString();
                    groutbound.error_code = httpStatus;
                    groutbound.error_body = responseBody.toString();
                    groutbound.retry_count = count;
                    groutbound.update();
                    var processTime = new GlideDateTime();
                    processTime.addSeconds(time);
                    gs.eventQueueScheduled();
                }
            } else {
                var errorMsg = parsedResponse.errorInfo && parsedResponse.errorInfo.length > 0 ? parsedResponse.errorInfo[0].msg : 'Unknown error';
                groutbound.state = 'Error';
                groutbound.response_body = responseBody.toString();
                groutbound.error_code = httpStatus;
                groutbound.error_body = responseBody.toString();
                groutbound.retry_count = count;
                groutbound.update();
                //gs.addErrorMessage('Attribute Sync Failed during API Call.' + 'Reason: ' + errorMsg);

            }
        }

    },
    //MSSTRUSTES-355
    validateAssignee: function() {
        var currentTaskAssignedTo = this.getParameter('sysparm_task_assigned_to');
        var parentCaseSysId = this.getParameter('sysparm_parent_id');

        if (!parentCaseSysId) {
            return false;
        }

        var parentGR = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case');
        if (parentGR.get(parentCaseSysId)) {
            var parentAssignedTo = parentGR.getValue('assigned_to');
            if (parentAssignedTo == currentTaskAssignedTo) {
                return true; // Conflict: Maker and Checker are the same
            }
        }
        return false; // No conflict
    },
    //MSSTRUSTES-499
    validateAssigneeComp: function() {
        var currentTaskAssignedTo = this.getParameter('sysparm_task_assigned_to');
