            }
        }
        return false; // No conflict
    },

    getMemberEmailID: function(sysId) { //MSSTRUSTES-337
        try {
            var emailArray = [];
            var grMember = new GlideRecord('sys_user_grmember');
            grMember.addQuery('group', sysId);
            grMember.query();
            while (grMember.next()) {
                var user = grMember.user.getRefRecord();
                if (user && user.email) {
                    emailArray.push(user.email.toString());
                }
            }
            return emailArray;
        } catch (e) {
            gs.error('Error in getMemberEmailID: ' + e.message);
            return [];
        }
    },

    sendEmail: function(email, num, sub, asignee, id, tablename) { //MSSTRUSTES-337
        try {
            var mailAddress = gs.getProperty('x_hsb11_mss_trus_0.Default Sender');
            var subject = "SLA " + sub + ' associated with ' + num + ' has breached';
            var baseUrl = gs.getProperty('glide.servlet.uri');
            var path = "x/hsb11/trustees-workspace/record/";
            var url = baseUrl + path + tablename + '/' + id;
            var body = "<p>Hello,</p>" +
                "<p>The SLA " + sub + " associated with " + num + ", assigned to " + asignee + ", has been breached.</p>" + "<p>View Record: <a href='" + url + "'>" + num + "</a></p>" +
                "<p>This is an auto-generated email. Please do not reply.</p>";
            var gr = new GlideRecord("x_hsb11_hsbcmss_qw_hsbc_qtrack_email_outbound");
            gr.initialize();
            gr.source_table = tablename;
            gr.sys_scope = "b208a7c083689e50c6695855eeaad3d2";
            gr.document_id = id;
            gr.to = email.join(',');
            //gr.to ="HSSQTrack020@adrestest.addev.hsbc, HSSQTrack020@adrestest.addev.hsbc";
            gr.email_body = body;
            gr.email_subject = subject;
            gr.request_date = new GlideDateTime();
            gr.classification = 'Restricted';
            gr.from = mailAddress;
            gr.insert();
        } catch (e) {
            gs.error('Error in sendEmail: ' + e.message);
        }
    },
    setReason: function() {
        var caseId = this.getParameter('sysparm_case_id');
        var reason = this.getParameter('sysparm_reason');
        var comment = this.getParameter('sysparm_cmt');
        var gr = new GlideRecord('x_hsb11_mss_trus_0_aml_kyc_case_task');
        if (gr.get(caseId)) {
            gr.setValue('return_case_aml', reason);
            gr.work_notes = comment;
            gr.stage = '500';
            gr.update();
            var grCase = new GlideRecord("x_hsb11_mss_trus_0_aml_kyc_case");
            grCase.get(gr.aml_kyc_case);
            if (reason == '085fd0041bdbe210cf016467b04bcb33')
                grCase.work_notes = "Return Reason: " + reason;
            else
                grCase.work_notes = "Return Reason: " + reason + '    ' + 'Details: ' + comment;
            grCase.update();
            return 'success' + ' ' + comment;
        }
        return 'not_found';
    },

    saveButtonVisibility: function(current) { //MSSTRUSTES-513
        // Condition for users with 'ops_admin' role
        if (gs.hasRole('x_hsb11_mss_trus_0.complaint_admin') && (current.state == '1' || current.state == '2')) {
            return true;
        }
        // Condition for users with 'complaint_maker' role
        if (gs.hasRole('x_hsb11_mss_trus_0.complaint_maker')) {
            if (current.isNewRecord()) {
                return true;
            }
            if (current.state == '2' && !current.assigned_to.nil()) {
                return true;
            }
        }
        // If none of the above conditions are met, hide the button
        return false;
    },

    validateAttachment: function() {
        gs.info('sanofi in');
        var id = this.getParameter('sysparam_id'); // Get the sys_id of the record
        gs.info('Sanofi sysparam_id: ' + id); // Debugging log

        var gr = new GlideRecord("sys_attachment");
        gr.addQuery('table_name', 'x_hsb11_mss_trus_0_complaint_case');
        gr.addQuery('table_sys_id', id); // Query attachments for the given record
        gr.query();

        var attachmentCount = 0;
        var maxFileSize = 5 * 1024 * 1024; // 5 MB in bytes

        while (gr.next()) {
            attachmentCount++;
            gs.info('Sanofi Attachment Name: ' + gr.getValue('file_name')); // Debugging log
            gs.info('Sanofi Attachment Size: ' + gr.getValue('size_bytes')); // Debugging log

            // Check if the file size exceeds 5 MB
            if (parseInt(gr.getValue('size_bytes'), 10) > maxFileSize) {
                return 'Attachment size must not exceed 5 MB';
            }

            // // Check if there is more than one attachment
            // if (attachmentCount > 1) {
            //     return 'You can only upload one attachment.If multiple files ZIP it.';
            // }
        }

        // If no issues, return true
        return true;
    },

